var n=[{title:`Een voorschrift lezen`,text:`„3 × 8–12, rust 90 s” betekent drie werksets van acht tot twaalf beheerste herhalingen, met ongeveer 90 seconden tussen de sets. Warming-upsets staan er los van, tenzij een schema zegt dat ze meetellen. Controleer bij een eenzijdige (unilaterale) oefening of „10 herhalingen” per kant is of in totaal.`},{title:`Wat rust doet`,text:`Rust laat je energierijke substraten, je ademhaling en je vermogen om kracht te leveren deels herstellen. Als maximale kracht de prioriteit is, kunnen enkele minuten tussen zware sets, meestal ongeveer twee tot vijf, helpen om het gewicht en de kwaliteit van je herhalingen te behouden. Voor spiergroei is ongeveer één tot drie minuten een praktisch bereik, al telt genoeg herstellen om je sets productief te houden zwaarder dan een strikte timer. Korte rust kan nuttig zijn bij lichter uithoudings- of circuitwerk, maar kan je output in latere sets verlagen.`},{title:`Doelen veranderen de combinatie`,text:`Vijf zware herhalingen met lange rust trainen iets anders dan twintig lichtere herhalingen met korte rust. Geen van beide schema’s is voor alles beter. De oefening telt ook mee, want zware squats vragen meestal meer herstel dan lichte zijwaartse heffingen.`},{title:`Voorbeeld`,text:`Stel dat je 10, 9 en 7 push-ups doet omdat rust van 30 seconden te kort is. Als je goed kracht- of hypertrofiewerk wilt, kan 90–120 seconden rust je in het geplande herhalingsbereik houden. Als het doel conditie is, kan de vermoeidheid door korte rust bedoeld zijn.`},{title:`TrainUp gebruiken`,text:`Elke oefening in je schema komt met sets, herhalingen of een houdtijd en rust, en de rusttimer telt de rust voor je. Volg ze, maar zet veilige techniek voorop. Leg de herhalingen vast die je echt hebt gedaan en beoordeel daarna de inspanning van de sessie. Als je latere sets steeds ver onder het doel blijven, kijk dan naar het gewicht, de rustduur en het totale werk in de sessie.`}];var r=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Onderzoek naar rust tussen sets en volume`,url:`https://doi.org/10.1519/jsc.0000000000003668`}];var i={sections:n,sources:r};export{i as default,n as sections,r as sources};